CREATE TABLE agents (id TEXT PRIMARY KEY, name TEXT, source_path TEXT, description TEXT, version TEXT);
CREATE TABLE projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, source_path TEXT UNIQUE, description TEXT, version TEXT);
CREATE TABLE recipes (id TEXT PRIMARY KEY, source_path TEXT UNIQUE, description TEXT, version TEXT);
CREATE TABLE skills (id TEXT PRIMARY KEY, source_path TEXT UNIQUE, description TEXT, version TEXT);
CREATE TABLE workflows (id TEXT PRIMARY KEY, source_path TEXT UNIQUE, description TEXT, version TEXT);
CREATE TABLE capabilities (id TEXT PRIMARY KEY, type TEXT NOT NULL, execution_lane TEXT NOT NULL, source_path TEXT, description TEXT, priority INTEGER DEFAULT 0, version TEXT);
CREATE TABLE capability_aliases (capability_id TEXT NOT NULL REFERENCES capabilities(id) ON DELETE CASCADE, value TEXT NOT NULL, PRIMARY KEY(capability_id,value));
CREATE TABLE capability_use_when (capability_id TEXT NOT NULL REFERENCES capabilities(id) ON DELETE CASCADE, value TEXT NOT NULL, PRIMARY KEY(capability_id,value));
CREATE TABLE capability_avoid_when (capability_id TEXT NOT NULL REFERENCES capabilities(id) ON DELETE CASCADE, value TEXT NOT NULL, PRIMARY KEY(capability_id,value));
CREATE TABLE fastpaths (intent TEXT PRIMARY KEY, status TEXT NOT NULL CHECK(status IN ('stable','probation','retired')), added_at TEXT NOT NULL DEFAULT (datetime('now')), last_seen_at TEXT, hit_count_7d INTEGER NOT NULL DEFAULT 0, recipe_path TEXT, handler_path TEXT, cli TEXT, stop_rule TEXT, capability_id TEXT REFERENCES capabilities(id), project_path TEXT, evidence TEXT);
CREATE TABLE fastpath_match_terms (intent TEXT NOT NULL REFERENCES fastpaths(intent) ON DELETE CASCADE, term TEXT NOT NULL, PRIMARY KEY(intent,term));
CREATE TABLE fastpath_lookup_order (intent TEXT NOT NULL REFERENCES fastpaths(intent) ON DELETE CASCADE, position INTEGER NOT NULL, value TEXT NOT NULL, PRIMARY KEY(intent,position));
CREATE TABLE agent_projects (agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, PRIMARY KEY(agent_id,project_id));
CREATE TABLE recipe_capabilities (recipe_id TEXT NOT NULL REFERENCES recipes(id) ON DELETE CASCADE, capability_id TEXT NOT NULL REFERENCES capabilities(id) ON DELETE CASCADE, PRIMARY KEY(recipe_id,capability_id));
CREATE TABLE project_domains (project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, domain TEXT NOT NULL, PRIMARY KEY(project_id,domain));
CREATE TABLE capability_sources (capability_id TEXT NOT NULL REFERENCES capabilities(id) ON DELETE CASCADE, source_path TEXT NOT NULL, PRIMARY KEY(capability_id,source_path));
